  const tokenizer = await asyncLoadTokenizer(
    modelUrl,
    curModelConfig,
    this.appConfig,
    this.logger,
    modelRecord.integrity,
  );
  await tvm.fetchTensorCache(modelUrl, tvm.webgpu(), {
    ...getTensorCacheAccessOptions("webllm/model", this.appConfig),
    signal: this.reloadController?.signal,
  });

